    val TYPE_AND_METHOD_PATTERNS: String =
        """
        |# ==============================================================================
        |# Declarative Rust Type-Path, Numeric Op & Method-Call Pattern/Replacement Rules
        |# ==============================================================================
        |# Authoritative declarative rules for:
        |# - `TypeReferenceEmitter.kt`
        |# - `ExpressionPrimitiveAndPointerOps.kt`
        |# - `ExpressionMethodCallEmitter.kt`
        |#
        |# Template placeholders use `{0}`, `{1}`, `{last}`, `{args}`, `{rawName}`, `{coreNs}`,
        |# `{recv}`, `{arg0}`, `{arg1}`, `{pointee}`, `{pointeeLayout}`, `{ptrCtor}`.
        |# Literal braces inside Kotlin code templates are escaped as `{{` and `}}`.
        |
        |# Ordered pattern-match and template-replacement rules for stdlib generic types.
        |# Rules are evaluated top-to-bottom; collection return/parameter types always target
        |# Kotlin collection interfaces (`List`, `MutableMap`, `MutableSet`) per Swift Export invariant.
        |stdlibGenericTypeRules:
        |  # Compiler/layout wrapper erased to its inner payload type unless locally declared.
        |  - match: "Padding"
        |    arity: 1
        |    unlessDeclared: true
        |    replace: "{0}"
        |
        |  # Uninitialized slot wrapper backed by `core::mem::MaybeUninit<T>`.
        |  - match: "MaybeUninit"
        |    arity: 1
        |    unlessDeclared: true
        |    imports: ["{coreNs}.mem.maybeuninit.MaybeUninit"]
        |    replace: "MaybeUninit<{0}>"
        |
        |  # Slice and Vec/Option iterator adapters lowered to `ArrayDeque<T>`.
        |  - match: "Iter IterMut"
        |    minArity: 1
        |    anySegmentIn: "slice"
        |    replace: "ArrayDeque<{0}>"
        |
        |  - match: "IntoIter"
        |    minArity: 1
        |    anySegmentIn: "vec option"
        |    replace: "ArrayDeque<{0}>"
        |
        |  # Interior mutability cells backed by `rustlang.core.cell`.
        |  - match: "Cell RefCell"
        |    arity: 1
        |    unlessDeclared: true
        |    imports: ["{coreNs}.cell.{rawName}"]
        |    replace: "{rawName}<{0}>"
        |
        |  - match: "OnceCell"
        |    arity: 1
        |    unlessDeclared: true
        |    imports: ["{coreNs}.cell.once.OnceCell"]
        |    replace: "OnceCell<{0}>"
        |
        |  # Stdlib containers, smart pointers, cows, and integer ranges.
        |  - match: "Vec"
        |    minArity: 1
        |    unlessDeclared: true
        |    replace: "List<{0}>"
        |
        |  - match: "Cow"
        |    minArity: 1
        |    unlessDeclared: true
        |    replace: "{last}"
        |
        |  - match: "Range RangeInclusive"
        |    arity: 1
        |    arg0Equals: "Int"
        |    unlessDeclared: true
        |    replace: "IntRange"
        |
        |  - match: "Box Rc Arc NoDrop ManuallyDrop"
        |    minArity: 1
        |    unlessDeclared: true
        |    replace: "{0}"
        |
        |  - match: "HashMap BTreeMap"
        |    minArity: 2
        |    unlessDeclared: true
        |    replace: "MutableMap<{0}, {1}>"
        |
        |  - match: "HashSet BTreeSet"
        |    minArity: 1
        |    unlessDeclared: true
        |    replace: "MutableSet<{0}>"
        |
        |# Unqualified Rust scalar type names lowered through `emitter.kotlinBuiltinTypeName(...)`.
        |builtinScalarTypes:
        |  i8: Byte
        |  i16: Short
        |  i32: Int
        |  i64: Long
        |  isize: Int
        |  u8: UByte
        |  u16: UShort
        |  u32: UInt
        |  u64: ULong
        |  usize: Int
        |  f64: Double
        |  bool: Boolean
        |  str: String
        |  char: Char
        |
        |# Self-contained `libc::<ty>` scalar typedefs when no external `libc` crate namespace is bound.
        |libcSelfContainedPtrWidth64Types:
        |  - value: "ULong"
        |    keys: "size_t usize uintptr_t"
        |  - value: "Long"
        |    keys: "ssize_t isize intptr_t ptrdiff_t"
        |
        |libcSelfContainedPtrWidth32Types:
        |  - value: "UInt"
        |    keys: "size_t usize uintptr_t"
        |  - value: "Int"
        |    keys: "ssize_t isize intptr_t ptrdiff_t"
        |
        |libcSelfContainedFixedScalarTypes:
        |  - value: "Byte"
        |    keys: "int8_t"
        |  - value: "UByte"
        |    keys: "uint8_t"
        |  - value: "Short"
        |    keys: "int16_t"
        |  - value: "UShort"
        |    keys: "uint16_t"
